$bytes = [Convert]::FromBase64String($base64)
$sha = [Security.Cryptography.SHA256]::Create()
try { $actualHash = ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
if ($actualHash -ne $expectedZipHash) { throw 'Bundle ZIP hash mismatch.' }
Add-Type -AssemblyName System.IO.Compression
$stream = [IO.MemoryStream]::new($bytes)
$zip = [IO.Compression.ZipArchive]::new($stream, [IO.Compression.ZipArchiveMode]::Read)
try {
    $rootPrefix = $destination.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
    $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($entry in $zip.Entries) {
        $target = [IO.Path]::GetFullPath((Join-Path $destination $entry.FullName))
        if (-not $target.StartsWith($rootPrefix, [StringComparison]::OrdinalIgnoreCase)) { throw 'Unsafe archive path.' }
        if (-not $seen.Add($target)) { throw 'Duplicate archive path.' }
    }
    [IO.Directory]::CreateDirectory($destination) | Out-Null
    foreach ($entry in $zip.Entries) {
        $target = Join-Path $destination $entry.FullName
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target)) | Out-Null
        $inputStream = $entry.Open()
        $outputStream = [IO.File]::Open($target, [IO.FileMode]::CreateNew)
        try { $inputStream.CopyTo($outputStream) } finally { $outputStream.Dispose(); $inputStream.Dispose() }
    }
} finally { $zip.Dispose(); $stream.Dispose() }
$checks = Get-Content -LiteralPath (Join-Path $destination 'SHA256SUMS.json') -Raw | ConvertFrom-Json
foreach ($check in $checks) {
    $actual = (Get-FileHash -LiteralPath (Join-Path $destination $check.path) -Algorithm SHA256).Hash
    if ($actual -ne $check.sha256) { throw "File hash mismatch: $($check.path)" }
}
$count = @(Get-ChildItem -LiteralPath $destination -Recurse -File).Count
if ($count -ne (@($checks).Count + 1)) { throw 'Extracted file count mismatch.' }
Write-Output "Verified $count extracted files in $destination"
Write-Output 'Read INTEGRATION.md first. No SQL, build, package installation, or DI changes were executed.'
